import sqlite3
import json
import ast
from typing import Any, Dict, Optional

import pandas as pd

# Optional vector rerank dependencies
# pip install pymilvus sentence-transformers
try:
    from pymilvus import connections, Collection
    from sentence_transformers import SentenceTransformer
    VECTOR_AVAILABLE = True
except Exception:
    VECTOR_AVAILABLE = False


# -------------------------------
# Exact required configuration
# -------------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def _safe_parse_attributes(x: Any) -> Dict[str, Any]:
    """Parse Yelp business.attributes which may be NULL, dict, JSON string, or python-literal string."""
    if x is None or (isinstance(x, float) and pd.isna(x)):
        return {}
    if isinstance(x, dict):
        return x
    if isinstance(x, (bytes, bytearray)):
        x = x.decode("utf-8", errors="ignore")
    if not isinstance(x, str):
        return {}

    s = x.strip()
    if not s:
        return {}

    # Try JSON
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        pass

    # Try python literal (common in some exports)
    try:
        obj = ast.literal_eval(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def _truthy(v: Any) -> Optional[bool]:
    """Convert 'True'/'False'/'1'/'0'/bool to bool; return None if unknown."""
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return bool(v)
    if isinstance(v, str):
        t = v.strip().lower()
        if t in {"true", "1", "yes", "y"}:
            return True
        if t in {"false", "0", "no", "n"}:
            return False
    return None


def preference_score(attrs: Dict[str, Any]) -> int:
    """Heuristic: '2-3 people dining together' preference."""
    score = 0

    gfg = _truthy(attrs.get("RestaurantsGoodForGroups"))
    if gfg is True:
        score += 2

    reserv = _truthy(attrs.get("RestaurantsReservations"))
    if reserv is True:
        score += 1

    # Ambience sometimes is dict or a stringified dict
    ambience = attrs.get("Ambience")
    if isinstance(ambience, str):
        try:
            ambience = json.loads(ambience)
        except Exception:
            try:
                ambience = ast.literal_eval(ambience)
            except Exception:
                ambience = None

    if isinstance(ambience, dict):
        if _truthy(ambience.get("intimate")) is True:
            score += 1
        if _truthy(ambience.get("romantic")) is True:
            score += 1

    return score


def fetch_candidates(city: str = "Sparks", min_stars: float = 4.2, min_reviews: int = 120) -> pd.DataFrame:
    """Step 1: SQL filtering."""
    db_path = sqlite_paths["business"]
    sql = """
    SELECT business_id, name, address, city, state, postal_code,
           stars, review_count, categories, attributes
    FROM business
    WHERE city = ?
      AND categories LIKE '%Chinese%'
      AND stars >= ?
      AND review_count >= ?
    ORDER BY stars DESC, review_count DESC;
    """

    with sqlite3.connect(db_path) as conn:
        df = pd.read_sql_query(sql, conn, params=(city, min_stars, min_reviews))

    return df


def rank_by_attributes(df: pd.DataFrame) -> pd.DataFrame:
    """Step 2: soft preference scoring from attributes."""
    if df.empty:
        return df

    parsed = df["attributes"].apply(_safe_parse_attributes)
    df = df.copy()
    df["parsed_attributes"] = parsed
    df["group_pref_score"] = df["parsed_attributes"].apply(preference_score)

    # Add some readable flags
    df["good_for_groups"] = df["parsed_attributes"].apply(lambda a: _truthy(a.get("RestaurantsGoodForGroups")))
    df["reservations"] = df["parsed_attributes"].apply(lambda a: _truthy(a.get("RestaurantsReservations")))

    df = df.sort_values(by=["group_pref_score", "stars", "review_count"], ascending=[False, False, False])
    return df


def milvus_semantic_rerank(df: pd.DataFrame, topk_per_review_search: int = 30, topm_aggregate: int = 5) -> pd.DataFrame:
    """Step 3 (optional): semantic rerank using Milvus reviews vectors.

    Assumptions (common pattern): Milvus 'reviews' collection has fields:
      - embedding vector field named 'embedding' (or similar)
      - scalar field 'business_id' (string)
    If your schema differs, adjust vector_field and output_fields.
    """
    if df.empty:
        return df
    if not VECTOR_AVAILABLE:
        # Can't do vector rerank; return original
        return df

    # Connect Milvus
    connections.connect(alias="default", host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])
    col_name = milvus_config['milvus_collections']['reviews']
    col = Collection(col_name)

    # Prepare embedding
    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    query_text = "Chinese restaurant good for two or three people, small group, date night, intimate"
    qvec = model.encode([query_text], normalize_embeddings=True)[0].tolist()

    # Build filter: business_id in [..]
    # Milvus filter syntax needs quoting; keep list reasonably sized.
    biz_ids = df["business_id"].astype(str).tolist()
    quoted = ",".join([f"'{bid}'" for bid in biz_ids])
    expr = f"business_id in [{quoted}]"

    # NOTE: you may need to adjust 'embedding' to your actual vector field name.
    vector_field = "embedding"

    # Search
    res = col.search(
        data=[qvec],
        anns_field=vector_field,
        param={"metric_type": "IP", "params": {"nprobe": 16}},
        limit=topk_per_review_search,
        expr=expr,
        output_fields=["business_id"],
        consistency_level="Strong"
    )

    # Aggregate similarity per business_id
    scores: Dict[str, list] = {}
    for hit in res[0]:
        b = None
        try:
            b = hit.entity.get("business_id")
        except Exception:
            # Some pymilvus versions: hit.fields
            try:
                b = hit.fields.get("business_id")
            except Exception:
                b = None
        if b is None:
            continue
        scores.setdefault(str(b), []).append(float(hit.score))

    def agg(bid: str) -> float:
        arr = sorted(scores.get(str(bid), []), reverse=True)[:topm_aggregate]
        return float(sum(arr) / len(arr)) if arr else 0.0

    out = df.copy()
    out["semantic_score"] = out["business_id"].astype(str).apply(agg)

    # Combine: keep your attribute preference primary, semantic as tie-breaker
    out = out.sort_values(by=["group_pref_score", "semantic_score", "stars", "review_count"], ascending=[False, False, False, False])
    return out


def main():
    # Step 1
    candidates_df = fetch_candidates(city="Sparks", min_stars=4.2, min_reviews=120)

    if candidates_df.empty:
        print("No matching Chinese restaurants found in Sparks with stars>=4.2 and review_count>=120.")
        return

    # Step 2
    ranked_df = rank_by_attributes(candidates_df)

    # Step 3 (optional)
    # If you don't want Milvus rerank, set use_vector_rerank=False
    use_vector_rerank = False
    final_df = milvus_semantic_rerank(ranked_df) if use_vector_rerank else ranked_df

    # Display
    cols = [
        "name", "stars", "review_count",
        "group_pref_score", "good_for_groups", "reservations",
        "address", "city", "state", "postal_code",
        "categories", "business_id"
    ]
    cols = [c for c in cols if c in final_df.columns]

    print("Top matches:")
    print(final_df[cols].head(15).to_string(index=False))


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"Error: {e}")

